let lesson,days,view='lesson',part=0,quizIndex=1;let state={done:false,scores:{}};try{state={...state,...JSON.parse(localStorage.getItem('toeic-studio')||'{}')}}catch{}
const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const save=()=>{try{localStorage.setItem('toeic-studio',JSON.stringify(state))}catch{};updateProgress()};function updateProgress(){$('#progress').innerHTML=`${state.done?1:0} <small>/ 90 天</small>`;$('#bar').style.width=(state.done?100/90:0)+'%'}
function inline(s){return esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function md(s){let out='',table=false,list=false;for(let line of s.split('\n')){if(!line.startsWith('|')&&table){out+='</tbody></table>';table=false}if(!/^[-*] /.test(line)&&list){out+='</ul>';list=false}if(/^\|/.test(line)){if(/^\|[\s:|-]+\|$/.test(line))continue;if(!table){out+='<table><tbody>';table=true}out+='<tr>'+line.split('|').slice(1,-1).map(x=>'<td>'+inline(x.trim())+'</td>').join('')+'</tr>';continue}if(/^[-*] /.test(line)){if(!list){out+='<ul>';list=true}out+='<li>'+inline(line.slice(2))+'</li>';continue}if(/^#{1,4} /.test(line)){out+='<h3>'+inline(line.replace(/^#+ /,''))+'</h3>'}else if(line.startsWith('>'))out+='<blockquote>'+inline(line.slice(1).trim())+'</blockquote>';else if(line==='---')out+='<hr>';else if(line.trim())out+='<p>'+inline(line)+'</p>'}return out+(table?'</tbody></table>':'')+(list?'</ul>':'')}
const groups=[{name:'學習概覽',ids:[0]},{name:'30 個核心單字',ids:[1]},{name:'文法總複習',ids:[2,3,4,5,6,7]},{name:'聽力階段模考',ids:[8,9,10,11]},{name:'雙篇閱讀',ids:[12,13]},{name:'Part 5 仿真題',ids:[14]},{name:'階段小考與解析',ids:[15,16]},{name:'錯題回收與作業',ids:[17,18,19,20]}];
function navigate(v){speechSynthesis?.cancel();view=v;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));render()}
function render(){const titles={lesson:['今天，讓知識串起來。','第四週總複習，練習從資訊中找出真正的答案。'],calendar:['你的 90 天學習旅程','已匯入 Day 28；其餘教材準備好後，就能接續學習。'],words:['讓單字，成為你的直覺。','第四週核心 30 字，搭配一起記更牢。'],quiz:['檢查你的高分實力。','完成作答後提交，看看哪些觀念需要再練習。']};$('#page-title').textContent=titles[view][0];$('#page-sub').textContent=titles[view][1];let html='';if(view==='lesson'){html=`<div class="lesson-layout"><div><section class="card lesson-intro"><div class="eyebrow">TODAY'S LESSON</div><h2>第四週總複習＋階段模考</h2><p>結構判斷・資訊整合・時間線推論</p><span class="pill">30 核心單字</span><span class="pill">3 組聽力</span><span class="pill">雙篇閱讀</span><span class="pill">30 題練習</span></section><article class="card"><div class="section-head"><h2>${groups[part].name}</h2><span class="muted">${part+1} / 8</span></div><div class="read-area">${groups[part].ids.map(i=>{const sec=lesson.sections[i];let text=sec.markdown;if(i>=8&&i<=10){const split=text.indexOf('聽力稿：');if(split>=0){let before=text.slice(0,split),after=text.slice(split);return '<h3>'+esc(sec.title)+'</h3><div class="listen"><button class="secondary" data-speak="'+i+'">▶ 朗讀聽力稿</button><button class="secondary" data-stop>停止</button></div><p class="muted">使用瀏覽器語音合成，非真人錄音。可先聽後作答。</p>'+md(before)+'<details><summary>查看聽力稿與答案解析</summary>'+md(after)+'</details>'}}const ai=text.search(/(?:### |## )?答案[：\n]/);if(ai>=0&&(i===12||i===14||i===15)){return '<h3>'+esc(sec.title)+'</h3>'+md(text.slice(0,ai))+'<details><summary>查看答案</summary>'+md(text.slice(ai))+'</details>'}return '<h3>'+esc(sec.title)+'</h3>'+md(text)}).join('')}</div><div class="section-head" style="margin-top:25px"><button class="secondary" id="previous" ${part===0?'disabled':''}>上一節</button><button class="primary" id="next">${part===7?(state.done?'已完成今日學習':'完成今日學習'):'下一節'}</button></div></article></div><div><nav class="card toc" aria-label="教材章節"><h3>今日學習路線</h3>${groups.map((g,i)=>`<button data-part="${i}" class="${i===part?'active':''}">${String(i+1).padStart(2,'0')}　${g.name}</button>`).join('')}</nav><div class="notice">本日教材已完整匯入。其他 89 天尚未取得內容。<br><a href="${lesson.sourceUrl}" target="_blank" rel="noopener">原始課程連結</a></div></div></div>`}else if(view==='calendar'){html='<div class="card"><div class="section-head"><h2>課程目錄</h2><span class="muted">1 / 90 天已匯入</span></div><div class="calendar">'+days.map(d=>`<button class="day ${d.available?'available':''}" ${d.available?'data-open-day':'disabled'} aria-label="Day ${d.day} ${d.title}"><span>DAY</span><b>${d.day}</b><span>${d.available?(state.done?'已完成':'開始學習'):'待匯入'}</span></button>`).join('')+'</div></div>'}else if(view==='words'){html='<div class="words">'+lesson.vocabulary.map((w,i)=>`<button class="card word" data-word="${i}" aria-label="朗讀 ${esc(w.word)}"><strong>${esc(w.word)} <small style="display:inline">♫</small></strong><small>${esc(w.meaning)}</small><span>${esc(w.phrase)}</span></button>`).join('')+'</div><p class="muted">點選單字卡聆聽發音。語音取決於瀏覽器支援。</p>'}else{let q=lesson.quizzes[quizIndex];html=`<div class="listen">${lesson.quizzes.map((x,i)=>`<button class="${i===quizIndex?'primary':'secondary'}" data-quiz="${i}">${i===0?'Part 5 仿真題':'Day 28 階段小考'} · ${x.questions.length} 題</button>`).join('')}</div><div class="notice">情境題參照今日聽力圖表與雙篇閱讀教材。提交後會顯示正解；重新作答可再次練習。${state.scores[quizIndex]!=null?' 上次成績：'+state.scores[quizIndex]+' / 15':''}</div><form id="quiz-form" class="card">${q.questions.map(x=>`<section class="quiz-q" id="question-${x.id}"><h3><span class="muted">${String(x.id).padStart(2,'0')} / 15</span><br>${inline(x.prompt)}</h3>${Object.entries(x.options).map(([k,v])=>`<label class="option"><input required type="radio" name="q${x.id}" value="${k}"><span>${k}. ${inline(v)}</span></label>`).join('')}<div class="feedback"></div></section>`).join('')}<div class="score" id="result" role="status"></div><button class="primary" type="submit">提交答案</button> <button class="secondary" type="button" id="retry">重新作答</button></form>`}$('#content').innerHTML=html;bind()}
function speak(text){if(!('speechSynthesis'in window)){alert('此瀏覽器不支援語音朗讀。');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.88;speechSynthesis.speak(u)}
function bind(){document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{part=+b.dataset.part;render()});$('#previous')?.addEventListener('click',()=>{part--;render()});$('#next')?.addEventListener('click',()=>{if(part<7)part++;else{state.done=true;save()}render();window.scrollTo({top:240,behavior:'smooth'})});document.querySelectorAll('[data-open-day]').forEach(b=>b.onclick=()=>navigate('lesson'));document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>speak(lesson.vocabulary[+b.dataset.word].word));document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>{const s=lesson.sections[+b.dataset.speak].markdown.split('聽力稿：')[1].split('答案：')[0];speak(s.replace(/^>\s?/gm,'').trim())});document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>speechSynthesis.cancel());document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{quizIndex=+b.dataset.quiz;render()});$('#retry')?.addEventListener('click',render);$('#quiz-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);let score=0;lesson.quizzes[quizIndex].questions.forEach(q=>{const a=data.get('q'+q.id),ok=a===q.answer;if(ok)score++;$('#question-'+q.id+' .feedback').innerHTML=`<p class="${ok?'correct':'wrong'}">${ok?'✓ 答對了':'答錯了 · 你的答案 '+esc(a)} · 正確答案 ${q.answer}：${inline(q.options[q.answer])}</p>`});state.scores[quizIndex]=score;save();$('#result').textContent=`${score} / 15 · ${score>=14?'掌握得很好！':score>=12?'再複習幾個觀念就更穩了。':'回到教材，釐清錯題的判斷依據。'}`;$('#result').scrollIntoView({behavior:'smooth',block:'center'})})}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));Promise.all([fetch('data/day-28.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('data/curriculum.json').then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([l,d])=>{lesson=l;days=d;updateProgress();render();if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_study_section',description:'Navigate to a Day 28 study section.',inputSchema:{type:'object',properties:{section:{type:'integer',minimum:0,maximum:7}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!Number.isInteger(input.section)||input.section<0||input.section>7)throw Error('Invalid section');part=input.section;navigate('lesson');return {day:28,section:groups[part].name}}})).catch(()=>{})}catch{}}}).catch(()=>{$('#content').innerHTML='<div class="card">教材載入失敗。請重新整理頁面再試一次。</div>'});
